
// Import ---------------------------------------

// Component ------------------------------------

function CustomerDetails( { account, setCustomerType } ) {

    // States -------------------------

    // Data ---------------------------

    // Functions/Methods --------------

    // Return UI ----------------------

    return (
        <>
        <h2>Customer Details</h2>
        {account === null ? <></> : 
            <input type="button" className="btn me-3 text-dark bg-white" value="Autofill Details" 
            onClick={ () => {
                setCustomerType(account.customer_type)
                document.getElementById(account.customer_type).checked = true
                document.getElementById("title").value = account.title
                document.getElementById("fname").value = account.fname
                document.getElementById("lname").value = account.lname
                document.getElementById("street").value = account.street
                document.getElementById("suburb").value = account.suburb
                document.getElementById("city").value = account.city
                document.getElementById("postcode").value = account.postcode
                document.getElementById("phone").value = account.phone
                document.getElementById("email").value = account.email
            }}/> }
        {/*Customer type*/}
        <div className="row p-1">
            <fieldset className="border border-primary col-12">
            <legend className="col-11 float-none w-auto">Customer Type</legend>
            <div className="form-check">
            <input className="form-check-input" type="radio" name="customer_type" id="Customer" value="Customer" required
                onChange={ event => setCustomerType(event.target.value) }/>
            <label className="form-check-label">Customer</label>
            </div>
            <div className="form-check">
            <input className="form-check-input" type="radio" name="customer_type" id="Business" value="Business"
                onChange={ event => setCustomerType(event.target.value) }/>
            <label className="form-check-label">Business</label>
            </div>
            </fieldset>
        </div>
        {/*Details*/}
        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Title</label>
            </div>
            <div className="col-12 col-lg-8">
                <select className="form-select" name="title" id="title">
                    <option value="Mr" defaultValue>Mr</option>
                    <option value="Mrs">Mrs</option>
                    <option value="Ms">Ms</option>
                    <option value="Miss">Miss</option>
                    <option value="Dr">Dr</option>
                </select>
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">First Name</label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="text" name="fname" id="fname" className="form-control"
                pattern="^[A-Za-z\s\-–]+$" title="Letters and Dashes only"
                required/>
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Last Name</label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="text" name="lname" id="lname" className="form-control"
                pattern="^[A-Za-z\s\-–]+$" title="Letters and Dashes only"
                required/>
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Street</label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="text" name="street" id="street" className="form-control" required/>
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Suburb <i>(Optional)</i></label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="text" name="suburb" id="suburb" className="form-control"/>
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">City</label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="text" name="city" id="city" className="form-control" required/>
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Post Code <i>(Optional)</i></label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="text" name="postcode" id="postcode" className="form-control"
                pattern="^[0-9]{4}" title="Postcode should be exactly 4 digits"/>
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Phone Number</label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="text" name="phone" id="phone" className="form-control" required/>
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Email</label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="text" name="email" id="email" className="form-control" required/>
            </div>
        </div>

        </>
    );
};

// Export Component -----------------------------

export default CustomerDetails;

