
// Import ---------------------------------------

import { useEffect } from 'react'
import { supabase } from '../supabase'

// Component ------------------------------------

function Account( { account, setAccount } ) {

    // States -------------------------

    // Data ---------------------------

    // Functions/Methods --------------

    const fillUserDetails = () => {
        if (account !== null) {
            document.getElementById("account"+account.customer_type).checked = true
            document.getElementById("accounttitle").value = account.title
            document.getElementById("accountfname").value = account.fname
            document.getElementById("accountlname").value = account.lname
            document.getElementById("accountstreet").value = account.street
            document.getElementById("accountsuburb").value = account.suburb
            document.getElementById("accountcity").value = account.city
            document.getElementById("accountpostcode").value = account.postcode
            document.getElementById("accountphone").value = account.phone
            document.getElementById("accountemail").value = account.email
            document.getElementById("accountpassword").value = account.password
        }
    }

    useEffect(() => { fillUserDetails() }, [account]);

    const signUp = async(event) => {
        // Prevent autosubmit behavior
        event.preventDefault();

        // Get all values at once
        const form_data = new FormData(event.target);
        const form_values = Object.fromEntries(form_data.entries());

        console.log(form_values);

        try {
            const { error } = await supabase.from('user_accounts').insert([form_values]);
            if (error) throw error;
            event.target.reset();
            login(form_values.email, form_values.password)
        } catch (error) {
            console.error('Error creating account:', error);
        }
    }

    const attemptLogin = event => {
        // Prevent autosubmit behavior
        event.preventDefault();

        // Get all values at once
        const form_data = new FormData(event.target);
        const form_values = Object.fromEntries(form_data.entries());
        login(form_values.email, form_values.password)
    }

    const login = async(email, password) => {
        try {
            const { data, error } = await supabase.from('user_accounts').select('*');
            if (error) throw error;
            const filter_data = data.filter( account =>
                account.email === email ||
                account.password === password
            )
            if (filter_data.length === 1) {
                setAccount(filter_data[0])
            }
        } catch (error) {
            console.error('Error fetching accounts:', error);
        }
    }

    const updateAccount = async(event) => {
        // Prevent autosubmit behavior
        event.preventDefault();

        // Get all values at once
        const form_data = new FormData(event.target);
        const form_values = Object.fromEntries(form_data.entries());

        console.log(form_values);
        console.log(account.id);

        try {
            const { error } = await supabase.from('user_accounts').update(form_values).eq('id', account.id).select();
            if (error) throw error;
            event.target.reset();
            login(form_values.email, form_values.password)
        } catch (error) {
            console.error('Error updating account:', error);
        }
    }

    // Return UI ----------------------

    return (
        <>
            <button type="button"  className="col-12 col-md-4 p-0 m-0 text-center text-white btn btn-primary" data-bs-toggle="modal" data-bs-target="#exampleModal">
                {account === null ? <>Login / Sign Up</> : <>Logged in as { account.fname } { account.lname }</>} 
            </button>
            <div className="modal fade" id="exampleModal" tabIndex="-1" role="dialog" aria-labelledby="exampleModalLabel" aria-hidden="true">
              <div className="modal-dialog" role="document">
                <div className="modal-content">
                  <div className="modal-body">
                    { account === null ? <>
                        <div className="accordion row align-items-start g-2" id="loginAccordian">
                            <div id="search" className="accordion-collapse collapse show" data-bs-parent="#loginAccordian">
                                <div className="accordion-body">
                                    <div className='row align-items-center'>
                                        <h2 className='col-6'>Login</h2>
                                        <div className='col-6'>
                                            <button className="accordion-button collapsed" type="button" data-bs-toggle="collapse" data-bs-target="#calendar" aria-expanded="false" aria-controls="calendar">
                                                New? Sign Up
                                            </button>
                                        </div>
                                    </div>
                                </div>
                                <form className="p-1" onSubmit={ attemptLogin }>
                                    <div className="row p-1">
                                        <div className="col-12 col-lg-4">
                                            <label className="col-form-label">Email</label>
                                        </div>
                                        <div className="col-12 col-lg-8">
                                            <input type="text" name="email" id="accountemail" className="form-control" required/>
                                        </div>
                                    </div>
                                    <div className="row p-1">
                                        <div className="col-12 col-lg-4">
                                            <label className="col-form-label">Password</label>
                                        </div>
                                        <div className="col-12 col-lg-8">
                                            <input type="password" name="password" id="accountpassword" className="form-control" required/>
                                        </div>
                                    </div>
                                    <div className="d-flex justify-content-center">
                                        <button type="button" className="btn btn-secondary m-2" data-bs-dismiss="modal">Cancel</button>
                                        <button type="submit" className="btn btn-primary m-2">Login</button>
                                    </div>
                                </form>
                            </div>
                            <div id="calendar" className="accordion-collapse collapse" data-bs-parent="#loginAccordian">
                                <div className="accordion-body">
                                    <div className='row align-items-center'>
                                        <h2 className='col-6'>Sign Up</h2>
                                        <div className='col-6'>
                                            <button className="accordion-button col-4" type="button" data-bs-toggle="collapse" data-bs-target="#search" aria-expanded="true" aria-controls="search">
                                                Have an Account? Login
                                            </button>
                                        </div>
                                    </div>
                                </div>
                                {/* Begining of Form */}
                                <form className="p-1" onSubmit={ signUp }>
                                    {/* Email/Password */}
                                    <div className="row p-1">
                                        <div className="col-12 col-lg-4">
                                            <label className="col-form-label">Email</label>
                                        </div>
                                        <div className="col-12 col-lg-8">
                                            <input type="text" name="email" id="accountemail" className="form-control" required/>
                                        </div>
                                    </div>
                                    <div className="row p-1">
                                        <div className="col-12 col-lg-4">
                                            <label className="col-form-label">Password</label>
                                        </div>
                                        <div className="col-12 col-lg-8">
                                            <input type="password" name="password" id="accountpassword" className="form-control" required/>
                                        </div>
                                    </div>

                                    <hr/>

                                    {/*Details*/}
                                    <div className="row p-1">
                                        <div className="col-12 col-lg-4">
                                            <label className="col-form-label">Customer Type</label>
                                        </div>
                                        <div className="col-12 col-lg-8">
                                            <div className="form-check">
                                                <input className="form-check-input" type="radio" name="customer_type" id="accountcustomer_type" value="Customer" required/>
                                                <label className="form-check-label">Customer</label>
                                            </div>
                                            <div className="form-check">
                                                <input className="form-check-input" type="radio" name="customer_type" id="accountcustomer_type" value="Business"/>
                                                <label className="form-check-label">Business</label>
                                            </div>
                                        </div>
                                    </div>
                                    <br/>
                                    <div className="row p-1">
                                        <div className="col-12 col-lg-4">
                                            <label className="col-form-label">Title</label>
                                        </div>
                                        <div className="col-12 col-lg-8">
                                            <select className="form-select" name="title" id="accounttitle">
                                                <option value="Mr" defaultValue>Mr</option>
                                                <option value="Mrs">Mrs</option>
                                                <option value="Ms">Ms</option>
                                                <option value="Miss">Miss</option>
                                                <option value="Dr">Dr</option>
                                            </select>
                                        </div>
                                    </div>

                                    <div className="row p-1">
                                        <div className="col-12 col-lg-4">
                                            <label className="col-form-label">First Name</label>
                                        </div>
                                        <div className="col-12 col-lg-8">
                                            <input type="text" name="fname" id="accountfname" className="form-control"
                                            pattern="^[A-Za-z\s\-–]+$" title="Letters and Dashes only"
                                            required/>
                                        </div>
                                    </div>

                                    <div className="row p-1">
                                        <div className="col-12 col-lg-4">
                                            <label className="col-form-label">Last Name</label>
                                        </div>
                                        <div className="col-12 col-lg-8">
                                            <input type="text" name="lname" id="accountlname" className="form-control"
                                            pattern="^[A-Za-z\s\-–]+$" title="Letters and Dashes only"
                                            required/>
                                        </div>
                                    </div>

                                    <div className="row p-1">
                                        <div className="col-12 col-lg-4">
                                            <label className="col-form-label">Street</label>
                                        </div>
                                        <div className="col-12 col-lg-8">
                                            <input type="text" name="street" id="accountstreet" className="form-control" required/>
                                        </div>
                                    </div>

                                    <div className="row p-1">
                                        <div className="col-12 col-lg-4">
                                            <label className="col-form-label">Suburb <i>(Optional)</i></label>
                                        </div>
                                        <div className="col-12 col-lg-8">
                                            <input type="text" name="suburb" id="accountsuburb" className="form-control"/>
                                        </div>
                                    </div>

                                    <div className="row p-1">
                                        <div className="col-12 col-lg-4">
                                            <label className="col-form-label">City</label>
                                        </div>
                                        <div className="col-12 col-lg-8">
                                            <input type="text" name="city" id="accountcity" className="form-control" required/>
                                        </div>
                                    </div>

                                    <div className="row p-1">
                                        <div className="col-12 col-lg-4">
                                            <label className="col-form-label">Post Code <i>(Optional)</i></label>
                                        </div>
                                        <div className="col-12 col-lg-8">
                                            <input type="text" name="postcode" id="accountpostcode" className="form-control"
                                            pattern="^[0-9]{4}" title="Postcode should be exactly 4 digits"/>
                                        </div>
                                    </div>

                                    <div className="row p-1">
                                        <div className="col-12 col-lg-4">
                                            <label className="col-form-label">Phone Number</label>
                                        </div>
                                        <div className="col-12 col-lg-8">
                                            <input type="text" name="phone" id="accountphone" className="form-control" required/>
                                        </div>
                                    </div>
                                    <div className="d-flex justify-content-center">
                                        <button type="button" className="btn btn-secondary m-2" data-bs-dismiss="modal">Cancel</button>
                                        <button type="submit" className="btn btn-primary m-2">Complete Sign Up</button>
                                    </div>
                                </form>
                            </div>
                        </div>
                    </> : <>
                        <h2>You're Signed In!</h2>
                        <div className="d-flex justify-content-center">
                            <button type="button" className="btn btn-secondary m-2" data-bs-dismiss="modal" onClick={ () => setAccount(null) }>Sign Out</button>
                            <button type="button" className="btn btn-primary m-2" data-bs-dismiss="modal">Return to Website</button>
                        </div>
                        <br/>
                        <br/>
                        <h3>Update Details</h3>
                        {/* Begining of Form */}
                        <form className="p-1" onSubmit={ updateAccount }>
                            {/* Email/Password */}
                            <div className="row p-1">
                                <div className="col-12 col-lg-4">
                                    <label className="col-form-label">Email</label>
                                </div>
                                <div className="col-12 col-lg-8">
                                    <input type="text" name="email" id="accountemail" className="form-control" required/>
                                </div>
                            </div>
                            <div className="row p-1">
                                <div className="col-12 col-lg-4">
                                    <label className="col-form-label">Password</label>
                                </div>
                                <div className="col-12 col-lg-8">
                                    <input type="password" name="password" id="accountpassword" className="form-control" required/>
                                </div>
                            </div>

                            <hr/>

                            {/*Details*/}
                            <div className="row p-1">
                                <div className="col-12 col-lg-4">
                                    <label className="col-form-label">Customer Type</label>
                                </div>
                                <div className="col-12 col-lg-8">
                                    <div className="form-check">
                                        <input className="form-check-input" type="radio" name="customer_type" id="accountCustomer" value="Customer" required/>
                                        <label className="form-check-label">Customer</label>
                                    </div>
                                    <div className="form-check">
                                        <input className="form-check-input" type="radio" name="customer_type" id="accountBusiness" value="Business"/>
                                        <label className="form-check-label">Business</label>
                                    </div>
                                </div>
                            </div>
                            <br/>
                            <div className="row p-1">
                                <div className="col-12 col-lg-4">
                                    <label className="col-form-label">Title</label>
                                </div>
                                <div className="col-12 col-lg-8">
                                    <select className="form-select" name="title" id="accounttitle">
                                        <option value="Mr" defaultValue>Mr</option>
                                        <option value="Mrs">Mrs</option>
                                        <option value="Ms">Ms</option>
                                        <option value="Miss">Miss</option>
                                        <option value="Dr">Dr</option>
                                    </select>
                                </div>
                            </div>

                            <div className="row p-1">
                                <div className="col-12 col-lg-4">
                                    <label className="col-form-label">First Name</label>
                                </div>
                                <div className="col-12 col-lg-8">
                                    <input type="text" name="fname" id="accountfname" className="form-control"
                                    pattern="^[A-Za-z\s\-–]+$" title="Letters and Dashes only"
                                    required/>
                                </div>
                            </div>

                            <div className="row p-1">
                                <div className="col-12 col-lg-4">
                                    <label className="col-form-label">Last Name</label>
                                </div>
                                <div className="col-12 col-lg-8">
                                    <input type="text" name="lname" id="accountlname" className="form-control"
                                    pattern="^[A-Za-z\s\-–]+$" title="Letters and Dashes only"
                                    required/>
                                </div>
                            </div>

                            <div className="row p-1">
                                <div className="col-12 col-lg-4">
                                    <label className="col-form-label">Street</label>
                                </div>
                                <div className="col-12 col-lg-8">
                                    <input type="text" name="street" id="accountstreet" className="form-control" required/>
                                </div>
                            </div>

                            <div className="row p-1">
                                <div className="col-12 col-lg-4">
                                    <label className="col-form-label">Suburb <i>(Optional)</i></label>
                                </div>
                                <div className="col-12 col-lg-8">
                                    <input type="text" name="suburb" id="accountsuburb" className="form-control"/>
                                </div>
                            </div>

                            <div className="row p-1">
                                <div className="col-12 col-lg-4">
                                    <label className="col-form-label">City</label>
                                </div>
                                <div className="col-12 col-lg-8">
                                    <input type="text" name="city" id="accountcity" className="form-control" required/>
                                </div>
                            </div>

                            <div className="row p-1">
                                <div className="col-12 col-lg-4">
                                    <label className="col-form-label">Post Code <i>(Optional)</i></label>
                                </div>
                                <div className="col-12 col-lg-8">
                                    <input type="text" name="postcode" id="accountpostcode" className="form-control"
                                    pattern="^[0-9]{4}" title="Postcode should be exactly 4 digits"/>
                                </div>
                            </div>

                            <div className="row p-1">
                                <div className="col-12 col-lg-4">
                                    <label className="col-form-label">Phone Number</label>
                                </div>
                                <div className="col-12 col-lg-8">
                                    <input type="text" name="phone" id="accountphone" className="form-control" required/>
                                </div>
                            </div>
                            <div className="d-flex justify-content-center">
                                <button type="button" className="btn btn-secondary m-2" data-bs-dismiss="modal">Cancel</button>
                                <button type="submit" className="btn btn-primary m-2">Update Details</button>
                            </div>
                        </form>
                    </> }
                  </div>
                </div>
              </div>
            </div>
        </>
    );
};

// Export Component -----------------------------

export default Account;

