
// Import ---------------------------------------
import { supabase } from './supabase'
import Search from './bookings/Search'
import Calendar from './bookings/Calendar'

import { useState, useEffect } from 'react';


// Component ------------------------------------

function Bookings() {

    // States -------------------------

    const [ bookings, updateBookings ] = useState([]);

    // Data ---------------------------

    // Functions/Methods --------------

    const retrieveBookings = async() => {
        try {
            const { data, error } = await supabase.from('repair_bookings').select('*');
            if (error) throw error;
            updateBookings( data );
            console.log(data);
        } catch (error) {
            console.error('Error fetching bookings:', error);
        }
    }

    useEffect( () => { retrieveBookings(); }, []);

    // Return UI ----------------------

    return (
        <>
            <div className="accordion row align-items-start g-2" id="bookingsAccordian">
                <div id="search" className="accordion-collapse collapse show" data-bs-parent="#bookingsAccordian">
                    <div className="accordion-body">
                        <div className='row'>
                            <h1 className='p-4 col-6 col-md-8 col-lg-10'>Bookings</h1>
                            <div className='col-6 col-md-4 col-lg-2'>
                                <button className="accordion-button collapsed" type="button" data-bs-toggle="collapse" data-bs-target="#calendar" aria-expanded="false" aria-controls="calendar">
                                    View Calendar
                                </button>
                            </div>
                        </div>
                    </div>
                    <Search bookings={ bookings } />
                </div>
                <div id="calendar" className="accordion-collapse collapse" data-bs-parent="#bookingsAccordian">
                    <div className="accordion-body">
                        <div className='row'>
                            <h1 className='p-4 col-6 col-md-8 col-lg-10'>Bookings Calendar</h1>
                            <div className='col-6 col-md-4 col-lg-2'>
                                <button className="accordion-button col-4" type="button" data-bs-toggle="collapse" data-bs-target="#search" aria-expanded="true" aria-controls="search">
                                    Search Bookings
                                </button>
                            </div>
                        </div>
                    </div>
                    <Calendar bookings={ bookings } />
                </div>
            </div>
        </>
    );
};

// Export Component -----------------------------

export default Bookings;

